1	// Package cursor implements the Agent interface for Cursor.
2	package cursor
3	
4	import (
5		"context"
6		"errors"
7		"fmt"
8		"log/slog"
9		"os"
10		"path/filepath"
11		"regexp"
12		"strings"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/agent"
16		"github.com/entireio/cli/cmd/entire/cli/agent/types"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/paths"
19	)
20	
21	// Compile-time interface assertion.
22	var _ agent.TranscriptPreparer = (*CursorAgent)(nil)
23	
24	//nolint:gochecknoinits // Agent self-registration is the intended pattern
25	func init() {
26		agent.Register(agent.AgentNameCursor, NewCursorAgent)
27	}
28	
29	// CursorAgent implements the Agent interface for Cursor.
30	//
31	//nolint:revive // CursorAgent is clearer than Agent in this context
32	type CursorAgent struct{}
33	
34	// NewCursorAgent creates a new Cursor agent instance.
35	func NewCursorAgent() agent.Agent {
36		return &CursorAgent{}
37	}
38	
39	// Name returns the agent registry key.
40	func (c *CursorAgent) Name() types.AgentName {
41		return agent.AgentNameCursor
42	}
43	
44	// Type returns the agent type identifier.
45	func (c *CursorAgent) Type() types.AgentType {
46		return agent.AgentTypeCursor
47	}
48	
49	// Description returns a human-readable description.
50	func (c *CursorAgent) Description() string {
51		return "Cursor - AI-powered code editor"
52	}
53	
54	func (c *CursorAgent) IsPreview() bool { return true }
55	
56	// DetectPresence checks if Cursor is configured in the repository.
57	func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
58		worktreeRoot, err := paths.WorktreeRoot(ctx)
59		if err != nil {
60			worktreeRoot = "."
61		}
62	
63		cursorDir := filepath.Join(worktreeRoot, ".cursor")
64		if _, err := os.Stat(cursorDir); err == nil {
65			return true, nil
66		}
67		return false, nil
68	}
69	
70	// GetSessionID extracts the session ID from hook input.
71	func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
72		return input.SessionID
73	}
74	
75	// ResolveSessionFile returns the path to a Cursor session file.
76	// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
77	// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
78	// We prefer nested if the file OR directory exists (the directory may be created
79	// before the file is flushed), otherwise fall back to flat.
80	func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
81		nestedDir := filepath.Join(sessionDir, agentSessionID)
82		nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
83		if _, err := os.Stat(nested); err == nil {
84			return nested
85		}
86		// IDE creates the directory before the transcript file — predict nested path.
87		if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
88			return nested
89		}
90		return filepath.Join(sessionDir, agentSessionID+".jsonl")
91	}
92	
93	// ProtectedDirs returns directories that Cursor uses for config/state.
94	func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
95	
96	// GetSessionDir returns the directory where Cursor stores session transcripts.
97	func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
98		if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
99			return override, nil
100		}
101	
102		homeDir, err := os.UserHomeDir()
103		if err != nil {
104			return "", fmt.Errorf("failed to get home directory: %w", err)
105		}
106	
107		projectDir := sanitizePathForCursor(repoPath)
108		return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
109	}
110	
111	// GetSessionBaseDir returns the base directory containing per-project session subdirectories.
112	// Unlike GetSessionDir, this does NOT use test overrides because the override
113	// points to a specific project dir, not the base containing all projects.
114	func (c *CursorAgent) GetSessionBaseDir() (string, error) {
115		homeDir, err := os.UserHomeDir()
116		if err != nil {
117			return "", fmt.Errorf("failed to get home directory: %w", err)
118		}
119		return filepath.Join(homeDir, ".cursor", "projects"), nil
120	}
121	
122	// ReadSession reads a session from Cursor's storage (JSONL transcript file).
123	// Note: ModifiedFiles is left empty because Cursor's transcript does not contain
124	// tool_use blocks for file detection. TranscriptAnalyzer extracts prompts and
125	// summaries; file detection relies on git status.
126	func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
127		if input.SessionRef == "" {
128			return nil, errors.New("session reference (transcript path) is required")
129		}
130	
131		data, err := os.ReadFile(input.SessionRef)
132		if err != nil {
133			return nil, fmt.Errorf("failed to read transcript: %w", err)
134		}
135	
136		return &agent.AgentSession{
137			SessionID:  input.SessionID,
138			AgentName:  c.Name(),
139			SessionRef: input.SessionRef,
140			StartTime:  time.Now(),
141			NativeData: data,
142		}, nil
143	}
144	
145	// PrepareTranscript waits for Cursor's transcript file to be flushed to disk.
146	// Cursor writes transcripts asynchronously; during mid-turn commits the file
147	// may not yet contain data. This polls until the file exists and is non-empty,
148	// or until the timeout expires.
149	func (c *CursorAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
150		const (
151			maxWait      = 3 * time.Second
152			pollInterval = 50 * time.Millisecond
153		)
154	
155		logCtx := logging.WithComponent(ctx, "agent.cursor")
156	
157		deadline := time.Now().Add(maxWait)
158		for time.Now().Before(deadline) {
159			info, err := os.Stat(sessionRef)
160			if err == nil {
161				if info.Size() > 0 {
162					logging.Debug(logCtx, "transcript file ready",
163						slog.Int64("size", info.Size()),
164					)
165					return nil
166				}
167			} else if !os.IsNotExist(err) {
168				return fmt.Errorf("failed to stat transcript %q: %w", sessionRef, err)
169			}
170			time.Sleep(pollInterval)
171		}
172	
173		logging.Warn(logCtx, "transcript file not ready within timeout, proceeding",
174			slog.Duration("timeout", maxWait),
175			slog.String("path", sessionRef),
176		)
177		return nil
178	}
