180	// WriteSession writes a session to Cursor's storage (JSONL transcript file).
181	func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
182		if session == nil {
183			return errors.New("session is nil")
184		}
185	
186		if session.AgentName != "" && session.AgentName != c.Name() {
187			return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
188		}
189	
190		if session.SessionRef == "" {
191			return errors.New("session reference (transcript path) is required")
192		}
193	
194		if len(session.NativeData) == 0 {
195			return errors.New("session has no native data to write")
196		}
197	
198		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
199			return fmt.Errorf("failed to write transcript: %w", err)
200		}
201	
202		return nil
203	}
