205	// FormatResumeCommand returns an instruction to resume a Cursor session.
206	// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
207	func (c *CursorAgent) FormatResumeCommand(_ string) string {
208		return "Open this project in Cursor to continue the session."
209	}
