211	// sanitizePathForCursor converts a path to Cursor's project directory format.
212	var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
213	
214	func sanitizePathForCursor(path string) string {
215		path = strings.TrimLeft(path, "/")
216		return nonAlphanumericRegex.ReplaceAllString(path, "-")
217	}
