219	// ChunkTranscript splits a JSONL transcript at line boundaries.
220	func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
221		chunks, err := agent.ChunkJSONL(content, maxSize)
222		if err != nil {
223			return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
224		}
225		return chunks, nil
226	}
