21	// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
22	// The CLI binary is called "agent" and uses Cursor's hooks system via
23	// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
24	//
25	// All E2E interactions use interactive (tmux) mode so that the full hook
26	// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
27	// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
28	type CursorCLI struct{}
29	
30	func (a *CursorCLI) Name() string               { return "cursor-cli" }
31	func (a *CursorCLI) Binary() string             { return "agent" }
32	func (a *CursorCLI) EntireAgent() string        { return "cursor" }
33	func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
34	
35	// PromptPattern returns a regex matching Cursor's ready-state prompt markers.
36	// Cursor has used multiple startup/completion markers across releases.
37	func (a *CursorCLI) PromptPattern() string {
38		return `(/ commands|Plan, search, build anything|Add a follow-up)`
39	}
40	
41	func (a *CursorCLI) IsTransientError(out Output, err error) bool {
42		if err == nil {
43			return false
44		}
45		if errors.Is(err, context.DeadlineExceeded) {
46			return true
47		}
48		combined := out.Stdout + out.Stderr
49		for _, p := range []string{
50			"overloaded",
51			"rate limit",
52			"429",
53			"503",
54			"529",
55			"ECONNRESET",
56			"ETIMEDOUT",
57			"server error",
58			"Internal Server Error",
59		} {
60			if strings.Contains(combined, p) {
61				return true
62			}
63		}
64		return false
65	}
