76	// cursorConfigDir creates an isolated per-session config directory for the
77	// Cursor CLI. Each session gets its own XDG_CONFIG_HOME so that parallel tests
78	// don't race on the shared ~/.config/cursor/cli-config.json file.
79	// The directory is pre-seeded with an empty cli-config.json to avoid the
80	// atomic temp-file rename that triggers the ENOENT race.
81	func cursorConfigDir() (string, error) {
82		tmp, err := os.MkdirTemp("", "cursor-e2e-config-*")
83		if err != nil {
84			return "", fmt.Errorf("create temp config dir: %w", err)
85		}
86		cursorDir := filepath.Join(tmp, "cursor")
87		if err := os.MkdirAll(cursorDir, 0o755); err != nil {
88			return "", fmt.Errorf("mkdir cursor config: %w", err)
89		}
90		if err := os.WriteFile(filepath.Join(cursorDir, "cli-config.json"), []byte("{}"), 0o644); err != nil {
91			return "", fmt.Errorf("seed cli-config.json: %w", err)
92		}
93		return tmp, nil
94	}
