96	func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
97		cfg := &runConfig{}
98		for _, o := range opts {
99			o(cfg)
100		}
101	
102		timeout := 90 * time.Second
103		if cfg.PromptTimeout > 0 {
104			timeout = cfg.PromptTimeout
105		}
106	
107		displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"
108	
109		// Start an interactive tmux session so all hooks fire
110		// (beforeSubmitPrompt and stop don't fire in headless -p mode).
111		s, err := a.startInteractiveSession(dir)
112		if err != nil {
113			return Output{Command: displayCmd, ExitCode: -1},
114				fmt.Errorf("start interactive session: %w", err)
115		}
116		defer s.Close()
117	
118		// Wait for trust dialog and accept it.
119		if err := a.acceptTrustDialogIfNeeded(s); err != nil {
120			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
121		}
122	
123		// Wait for the TUI to be ready.
124		if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
125			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
126				fmt.Errorf("waiting for startup prompt: %w", err)
127		}
128	
129		// Send the prompt.
130		if err := s.Send(prompt); err != nil {
131			return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
132				fmt.Errorf("sending prompt: %w", err)
133		}
134	
135		// Wait for the "Add a follow-up" text that only appears after the agent
136		// finishes processing. We cannot reuse PromptPattern() ("/ commands")
137		// because that text is always visible in the status bar — even during
138		// the "Thinking" phase — causing WaitFor to settle prematurely when the
139		// model takes >2s to start producing visible output.
140		content, waitErr := s.WaitFor(`Add a follow-up`, timeout)
141		if waitErr != nil {
142			// Check for deadline exceeded to allow transient error detection.
143			if ctx.Err() == context.DeadlineExceeded {
144				waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
145			}
146			return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
147		}
148	
149		return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
150	}
