152	func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
153		s, err := a.startInteractiveSession(dir)
154		if err != nil {
155			return nil, err
156		}
157	
158		if err := a.acceptTrustDialogIfNeeded(s); err != nil {
159			_ = s.Close()
160			return nil, err
161		}
162	
163		// Wait for the TUI to be ready (input prompt).
164		if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
165			_ = s.Close()
166			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
167		}
168		s.stableAtSend = ""
169	
170		return s, nil
171	}
