173	// startInteractiveSession creates a new tmux session running the Cursor CLI
174	// in interactive mode (no -p flag) so all hooks fire.
175	func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
176		// Resolve to absolute path so tmux can find the binary even if its
177		// shell doesn't inherit the test process's PATH (common on CI).
178		bin, err := exec.LookPath(a.Binary())
179		if err != nil {
180			return nil, fmt.Errorf("agent binary not found: %w", err)
181		}
182	
183		// Create an isolated config directory for this session so parallel tests
184		// don't race on the shared ~/.config/cursor/cli-config.json file.
185		configDir, err := cursorConfigDir()
186		if err != nil {
187			return nil, fmt.Errorf("create cursor config dir: %w", err)
188		}
189	
190		// Build env-wrapped command so the tmux session inherits critical env vars.
191		// tmux starts a new shell that doesn't inherit Go's os.Environ().
192		var envArgs []string
193		for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
194			if v := os.Getenv(key); v != "" {
195				envArgs = append(envArgs, key+"="+v)
196			}
197		}
198		// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
199		// there instead of ~/.config/cursor/. We keep the real HOME so that
200		// auth credentials (keychain, OAuth tokens) remain accessible.
201		envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)
202	
203		args := append([]string{"env"}, envArgs...)
204		args = append(args, bin, "--force", "--workspace", dir)
205	
206		name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
207		unset := []string{"CI"}
208		s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
209		if err != nil {
210			_ = os.RemoveAll(configDir)
211			return nil, err
212		}
213		s.OnClose(func() { _ = os.RemoveAll(configDir) })
214		return s, nil
215	}
216	
217	// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
218	// and presses "a" to accept it. The dialog only shows on the first launch in
219	// a workspace — subsequent sessions in the same directory skip it.
220	func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
221		// Race: either the trust dialog or the input prompt will appear first.
222		// Use a short timeout to check for the trust dialog without blocking
223		// too long if the workspace is already trusted.
224		content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
225		if err != nil {
226			return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
227		}
228		if strings.Contains(content, "Trust this workspace") {
229			if err := s.SendKeys("a"); err != nil {
230				return fmt.Errorf("accepting trust dialog: %w", err)
231			}
232		}
233		return nil
234	}
