715	// so only affected subtrees are read/rebuilt — O(changed dirs) instead of O(total files).
716	func (s *GitStore) buildTreeWithChanges(
717		ctx context.Context,
718		baseTreeHash plumbing.Hash,
719		modifiedFiles, deletedFiles []string,
720		metadataDir, metadataDirAbs string,
721	) (plumbing.Hash, error) {
722		// Get worktree root for resolving file paths
723		// This is critical because fileExists() and createBlobFromFile() use os.Stat()
724		// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
725		// so we must resolve them against repo root, not CWD.
726		repoRoot, err := paths.WorktreeRoot(ctx)
727		if err != nil {
728			return plumbing.ZeroHash, fmt.Errorf("failed to get worktree root: %w", err)
729		}
730	
731		// Build list of tree changes
732		changes := make([]TreeChange, 0, len(modifiedFiles)+len(deletedFiles))
733	
734		// Deleted files → nil Entry means deletion
735		for _, file := range deletedFiles {
736			relPath, relErr := normalizeRepoRelativeTreePath(repoRoot, file)
737			if relErr != nil {
738				logInvalidGitTreePath(ctx, "delete shadow branch entry", file, relErr)
739				continue
740			}
741			changes = append(changes, TreeChange{Path: relPath, Entry: nil})
742		}
743	
744		// Modified/new files → create blobs from disk
745		for _, file := range modifiedFiles {
746			relPath, relErr := normalizeRepoRelativeTreePath(repoRoot, file)
747			if relErr != nil {
748				logInvalidGitTreePath(ctx, "add shadow branch entry", file, relErr)
749				continue
750			}
751	
752			absPath := filepath.Join(repoRoot, filepath.FromSlash(relPath))
753			if !fileExists(absPath) {
754				// File disappeared since detection — treat as deletion
755				changes = append(changes, TreeChange{Path: relPath, Entry: nil})
756				continue
757			}
758	
759			blobHash, mode, blobErr := createBlobFromFile(s.repo, absPath)
760			if blobErr != nil {
761				// Skip files that can't be staged (may have been deleted since detection)
762				continue
763			}
764	
765			changes = append(changes, TreeChange{
766				Path: relPath,
767				Entry: &object.TreeEntry{
768					Mode: mode,
769					Hash: blobHash,
770				},
771			})
772		}
773	
774		// Metadata directory files
775		if metadataDir != "" && metadataDirAbs != "" {
776			metadataRel, relErr := normalizeRepoRelativeTreePath(repoRoot, metadataDir)
777			if relErr != nil {
778				logInvalidGitTreePath(ctx, "add metadata directory", metadataDir, relErr)
779			} else {
780				metaChanges, metaErr := addDirectoryToChanges(s.repo, metadataDirAbs, metadataRel)
781				if metaErr != nil {
782					return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", metaErr)
783				}
784				changes = append(changes, metaChanges...)
785			}
786		}
787	
788		return ApplyTreeChanges(ctx, s.repo, baseTreeHash, changes)
789	}
